import { createServer } from "node:http";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(__dirname, "data", "books.json");
const PORT = Number(process.env.PORT) || 3000;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

async function loadBooks() {
  try {
    const raw = await readFile(DATA_PATH, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch (error) {
    if (error.code === "ENOENT") return [];
    throw error;
  }
}

async function saveBooks(books) {
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n", "utf8");
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      const text = Buffer.concat(chunks).toString("utf8");
      const params = new URLSearchParams(text);
      resolve(Object.fromEntries(params));
    });
    req.on("error", reject);
  });
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #1a1a1a; }
    h1 { font-size: 1.75rem; margin-bottom: 0.25rem; }
    h2 { font-size: 1.1rem; margin: 1.75rem 0 0.5rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
    a { color: #1d4e89; }
    ul { list-style: none; padding: 0; margin: 0; }
    li { padding: 0.4rem 0; display: flex; gap: 0.75rem; align-items: baseline; justify-content: space-between; }
    .meta { color: #555; }
    form.inline { display: inline; }
    button, input[type="submit"] { font: inherit; cursor: pointer; }
    label { display: block; margin-top: 0.75rem; }
    input, textarea { width: 100%; box-sizing: border-box; font: inherit; padding: 0.4rem; }
    .actions { margin-top: 1rem; }
    .empty { color: #666; font-style: italic; }
    nav { margin: 0.5rem 0 1.5rem; }
  </style>
</head>
<body>
  <nav><a href="/">Books</a></nav>
  ${body}
</body>
</html>`;
}

function bookList(books, status) {
  const items = books.filter((book) => book.status === status);
  if (items.length === 0) return `<p class="empty">None yet.</p>`;
  return `<ul>${items
    .map(
      (book) => `<li>
        <span><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <span class="meta">by ${escapeHtml(book.author)}</span></span>
        ${
          status === "reading"
            ? `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
                 <button type="submit">Mark finished</button>
               </form>`
            : ""
        }
      </li>`
    )
    .join("")}</ul>`;
}

function homePage(books) {
  const reading = bookList(books, "reading");
  const finished = bookList(books, "finished");
  return layout(
    "Books",
    `<h1>Books</h1>
     <h2>Currently reading</h2>
     ${reading}
     <h2>Finished</h2>
     ${finished}
     <h2>Add a book</h2>
     <form method="post" action="/books">
       <label>Title <input name="title" required></label>
       <label>Author <input name="author" required></label>
       <label>Notes <textarea name="notes" rows="4"></textarea></label>
       <div class="actions"><button type="submit">Add book</button></div>
     </form>`
  );
}

function bookPage(book) {
  const finished = book.status === "finished";
  return layout(
    book.title,
    `<h1>${escapeHtml(book.title)}</h1>
     <p class="meta">by ${escapeHtml(book.author)}</p>
     <p class="meta">${finished ? "Finished" : "Currently reading"}</p>
     <h2>Notes</h2>
     <p>${book.notes ? escapeHtml(book.notes).replaceAll("\n", "<br>") : `<span class="empty">No notes yet.</span>`}</p>
     ${
       finished
         ? ""
         : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
              <button type="submit">Mark finished</button>
            </form>`
     }`
  );
}

function notFound() {
  return layout("Not found", `<h1>Not found</h1><p>That book isn't here.</p>`);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (method === "GET" && path === "/") {
      const books = await loadBooks();
      return send(res, 200, homePage(books));
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (method === "GET" && bookMatch) {
      const books = await loadBooks();
      const book = books.find((item) => item.id === decodeURIComponent(bookMatch[1]));
      if (!book) return send(res, 404, notFound());
      return send(res, 200, bookPage(book));
    }

    if (method === "POST" && path === "/books") {
      const body = await parseBody(req);
      const title = (body.title || "").trim();
      const author = (body.author || "").trim();
      if (!title || !author) {
        return send(res, 400, layout("Missing fields", `<h1>Title and author are required.</h1><p><a href="/">Back</a></p>`));
      }
      const books = await loadBooks();
      const book = {
        id: crypto.randomUUID(),
        title,
        author,
        notes: (body.notes || "").trim(),
        status: "reading",
      };
      books.push(book);
      await saveBooks(books);
      return redirect(res, `/books/${book.id}`);
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (method === "POST" && finishMatch) {
      const books = await loadBooks();
      const book = books.find((item) => item.id === decodeURIComponent(finishMatch[1]));
      if (!book) return send(res, 404, notFound());
      book.status = "finished";
      await saveBooks(books);
      return redirect(res, `/books/${book.id}`);
    }

    return send(res, 404, notFound());
  } catch (error) {
    console.error(error);
    return send(res, 500, layout("Error", `<h1>Something went wrong.</h1>`));
  }
});

server.listen(PORT, () => {
  console.log(`Reading list at http://localhost:${PORT}`);
});

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "node:child_process";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

const root = await mkdtemp(join(tmpdir(), "books-"));
const dataDir = join(root, "data");
const { mkdir } = await import("node:fs/promises");
await mkdir(dataDir);
await writeFile(join(dataDir, "books.json"), "[]\n");

const port = 3456 + Math.floor(Math.random() * 1000);
const child = spawn(process.execPath, ["server.js"], {
  cwd: process.cwd(),
  env: { ...process.env, PORT: String(port), DATA_OVERRIDE: root },
  stdio: ["ignore", "pipe", "pipe"],
});

function waitForServer() {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("server did not start")), 5000);
    const onData = (buf) => {
      if (String(buf).includes("Reading list")) {
        clearTimeout(timer);
        resolve();
      }
    };
    child.stdout.on("data", onData);
    child.stderr.on("data", (buf) => {
      clearTimeout(timer);
      reject(new Error(String(buf)));
    });
  });
}

describe("book tracker", () => {
  beforeAll(async () => {
    await waitForServer();
  });

  afterAll(async () => {
    child.kill();
    await rm(root, { recursive: true, force: true });
  });

  it("lists reading and finished books and can add, finish, and open one", async () => {
    const home = await fetch(`http://127.0.0.1:${port}/`);
    expect(home.status).toBe(200);
    const homeHtml = await home.text();
    expect(homeHtml).toContain("Currently reading");
    expect(homeHtml).toContain("Finished");

    const created = await fetch(`http://127.0.0.1:${port}/books`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ title: "The Left Hand of Darkness", author: "Ursula K. Le Guin", notes: "Winter." }),
      redirect: "manual",
    });
    expect(created.status).toBe(303);
    const location = created.headers.get("location");
    expect(location).toMatch(/^\/books\//);

    const page = await fetch(`http://127.0.0.1:${port}${location}`);
    const pageHtml = await page.text();
    expect(pageHtml).toContain("The Left Hand of Darkness");
    expect(pageHtml).toContain("Ursula K. Le Guin");
    expect(pageHtml).toContain("Winter.");

    const finished = await fetch(`http://127.0.0.1:${port}${location}/finish`, {
      method: "POST",
      redirect: "manual",
    });
    expect(finished.status).toBe(303);

    const after = await fetch(`http://127.0.0.1:${port}/`);
    const afterHtml = await after.text();
    expect(afterHtml).toContain("The Left Hand of Darkness");
    const finishedSection = afterHtml.split("<h2>Finished</h2>")[1];
    expect(finishedSection).toContain("The Left Hand of Darkness");
  });
});

