import { readFile, writeFile } from "node:fs/promises";
import { spawn } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, expect, test } from "vitest";

const root = dirname(fileURLToPath(import.meta.url));
const dataPath = join(root, "data", "books.json");
const original = await readFile(dataPath, "utf8");
await writeFile(dataPath, "[]\n");

const port = 18000 + Math.floor(Math.random() * 10000);
const child = spawn(process.execPath, ["server.js"], {
  cwd: root,
  env: { ...process.env, PORT: String(port) },
  stdio: ["ignore", "pipe", "pipe"],
});

async function waitForServer() {
  const deadline = Date.now() + 5000;
  while (Date.now() < deadline) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/`);
      if (res.ok) return;
    } catch {
      await new Promise((resolve) => setTimeout(resolve, 50));
    }
  }
  throw new Error(child.stderr ? "server did not start" : "server did not start");
}

beforeAll(async () => {
  await waitForServer();
});

afterAll(async () => {
  child.kill();
  await writeFile(dataPath, original);
});

test("shows lists, adds a book, opens it, and marks it finished", async () => {
  const home = await fetch(`http://127.0.0.1:${port}/`);
  expect(home.status).toBe(200);
  const homeHtml = await home.text();
  expect(homeHtml).toContain("Currently reading");
  expect(homeHtml).toContain("Finished");

  const created = await fetch(`http://127.0.0.1:${port}/books`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      title: "The Left Hand of Darkness",
      author: "Ursula K. Le Guin",
      notes: "Winter.",
    }),
    redirect: "manual",
  });
  expect(created.status).toBe(303);
  const location = created.headers.get("location");
  expect(location).toMatch(/^\/books\//);

  const page = await fetch(`http://127.0.0.1:${port}${location}`);
  const pageHtml = await page.text();
  expect(pageHtml).toContain("The Left Hand of Darkness");
  expect(pageHtml).toContain("Ursula K. Le Guin");
  expect(pageHtml).toContain("Winter.");

  const finished = await fetch(`http://127.0.0.1:${port}${location}/finish`, {
    method: "POST",
    redirect: "manual",
  });
  expect(finished.status).toBe(303);

  const after = await fetch(`http://127.0.0.1:${port}/`);
  const afterHtml = await after.text();
  const finishedSection = afterHtml.split("<h2>Finished</h2>")[1];
  expect(finishedSection).toContain("The Left Hand of Darkness");

  const saved = JSON.parse(await readFile(dataPath, "utf8"));
  expect(saved).toHaveLength(1);
  expect(saved[0].status).toBe("finished");
});
